import React, { useState } from 'react';
import { requestPasswordReset } from '../services/api'; 
import './ResetPasswordPage.css'; // Importar el CSS

const ResetPasswordPage = () => {
  const [resetEmail, setResetEmail] = useState('');
  const [message, setMessage] = useState('');

  const handlePasswordReset = async (e) => {
    e.preventDefault();
    try {
      const response = await requestPasswordReset({ email: resetEmail });
      setMessage(response.data.message);
    } catch (error) {
      setMessage('Error al enviar el email de reseteo.');
    }
  };

  return (
    <form onSubmit={handlePasswordReset} className="user-form">
      <h2 className="form-title">Olvidé mi contraseña</h2>
      <p className="form-subtitle">Ingresá tu email para recibir instrucciones de reseteo</p>

      <label htmlFor="resetEmail" className="input-label">Email</label>
      <input
        id="resetEmail"
        type="email"
        placeholder="EMAIL"
        value={resetEmail}
        onChange={(e) => setResetEmail(e.target.value)}
        required
        className="input-email"
      />

      <button type="submit" className="submit-button">Enviar</button>
      {message && <p className="message">{message}</p>} {/* Mensaje de confirmación */}

      <p className="forgot-password">
        <a href="/login">Volver a Iniciar Sesión</a>
      </p>
    </form>
  );
};

export default ResetPasswordPage;
